import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Sprite plane (from texture) ---
  const aspect = 512 / 320; // atlas region aspect ratio
  const planeWidth = 1.6;   // scene units – matched to hub scale
  const planeHeight = planeWidth / aspect;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff, // white fill until texture loads
    transparent: true,
  });
  const plane = new Mesh(geometry, material);
  // Rotate so plane faces camera (camera at +Z, plane normal should be -Z)
  plane.rotation.y = Math.PI;
  group.add(plane);

  // Load the engineered gradient / grain texture
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text overlay: "Features" ---
  const textContent = (config.textContent ?? config.intent?.visualSpec?.textContent ?? [])
    .find((t) => t.role === 'headline');
  const textStr = textContent?.text ?? 'Features';
  const fontSize = textContent?.typography?.fontSize ?? 96;
  const textGroup = ctx.fontAtlas.createText(textStr, {
    fontSize,
    color: '#e8ecf2',         // paper – maximum contrast on dark background
    align: 'center',
  });
  // Float slightly above the plane to avoid z‑fighting
  textGroup.position.z = 0.02;
  // Center the text on the plane (the text origin is its left baseline by default,
  // but alignment 'center' should place it around the origin).
  group.add(textGroup);

  // --- Cleanup ---
  group.userData.handlers = {};
  group.userData.cleanup = function () {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // fontAtlas resources are managed externally; no explicit cleanup needed
  };

  return group;
}
